import data from "../data/agent_search.json";

/**
 * How the Cortex agent answers once it can search Business Ontology, with the
 * before/after runs of the same questions. Generated by tools/export_agent_search.py.
 */
const TOOL_LABEL: Record<string, string> = {
  business_ontology: "Ontology search",
  system_execute_sql: "Ontology / data read",
};

function Tools({ tools }: { tools: string[] }) {
  if (!tools.length) return <span className="text-[11px] text-rose-600">no tool call</span>;
  return (
    <div className="flex flex-wrap gap-1">
      {tools.map((t) => (
        <span key={t} className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${
          t === "business_ontology" ? "bg-emerald-100 text-emerald-800" : "bg-slate-100 text-slate-600"}`}>
          {TOOL_LABEL[t] ?? t}
        </span>
      ))}
    </div>
  );
}

export function AgentSearch() {
  return (
    <section className="rounded-lg border border-emerald-200 bg-white p-4">
      <div className="text-[11px] font-semibold uppercase tracking-wide text-emerald-700">Cortex agent · Business Ontology search</div>
      <h2 className="mt-1 text-base font-bold text-slate-800">The agent looks up the governed meaning before it answers</h2>
      <p className="mt-1 text-sm text-slate-600">
        <code className="text-[12px]">{data.agent}</code> searches {data.domains}. Its answer gives the governed definition
        (<i>domain.concept</i>), then pulls numbers from the objects that concept is bound to, and labels each number
        <b> Governed</b>, <b>Derived</b> or <b>Bound table</b>. If no governed definition exists, it says so instead of guessing.
      </p>
      <ol className="mt-3 grid gap-2 text-[12px] text-slate-700 sm:grid-cols-3">
        <li className="rounded border border-slate-200 bg-slate-50 p-2"><b>1. Search</b>: find the concept, its definition and synonyms</li>
        <li className="rounded border border-slate-200 bg-slate-50 p-2"><b>2. Read</b>: relationships and the objects bound to the concept</li>
        <li className="rounded border border-slate-200 bg-slate-50 p-2"><b>3. Answer</b>: query the bound semantic view, cite the concept and source</li>
      </ol>
      <div className="mt-4 overflow-x-auto">
        <table className="w-full text-left text-[12px]">
          <thead className="text-[11px] uppercase text-slate-500">
            <tr><th className="py-1 pr-3">Question</th><th className="py-1 pr-3">Before</th><th className="py-1 pr-3">After</th><th className="py-1">What changed</th></tr>
          </thead>
          <tbody>
            {data.rows.map((r) => (
              <tr key={r.check} className="border-t border-slate-100 align-top">
                <td className="py-2 pr-3 font-medium text-slate-800">{r.question}</td>
                <td className="py-2 pr-3 text-slate-500"><Tools tools={r.before_tools} /><p className="mt-1">{r.before}</p></td>
                <td className="py-2 pr-3 text-slate-700"><Tools tools={r.after_tools} /><p className="mt-1">{r.after}</p></td>
                <td className="py-2 text-slate-700">{r.verdict}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-2 text-[11px] text-slate-500">Runs of {data.run_date}. {data.note}</p>
    </section>
  );
}
